                            business_index<=0; state<=BIZ_COPY;
                        end
                    end else if(business_handle==16 || business_handle==19 || business_handle==22) begin
                        if(captured_length!=13 || word_at(11)>1) att_error_response(8'h12,business_handle,8'h0d);
                        else begin
                            if(business_handle==16) response_subscribed<=packet[11][0];
                            if(business_handle==19) status_subscribed<=packet[11][0];
                            if(business_handle==22) begin transfer_subscribed<=packet[11][0];if(packet[11][0] && !fast_link_requested)fast_link_pending<=1;end
                            response_begin(4,1); response[response_base+8]=8'h13;
                        end
                    end else att_error_response(8'h12,business_handle,3);
                end
                8'h52: begin
                    // Optional transport acceleration advertised by property 0x04.
                    // Logical CRC/session/request-id retries remain unchanged.
                    // ATT forbids responses (including errors) to Write Command.
                    if(business_handle==13 && captured_length>=18 && captured_length<=31 && !bridge_busy) begin
                        fragment_length<=captured_length-11;
                        business_index<=0;state<=BIZ_COPY;
                    end
                end
                default:att_error_response(packet[8],business_handle,6);
            endcase
        end
    endtask

    // ATT MTU up to247. Legacy attributes still return their original values:
    // GAP/device-name, GATT, FFF0 service, read+notify FFF1 and CCCD.
    task process_att;
        reg first_in_range, second_in_range, third_in_range;
        begin
            start_handle=word_at(9); end_handle=word_at(11);
            attribute_type=word_at(13);
            case(packet[8])
                8'h02: begin
                    if(captured_length!=11) att_error_response(2,0,8'h04);
                    else if(mtu_exchanged)att_error_response(2,0,6);
                    else begin
                        response_begin(4,3); response[response_base+8]=3;
                        response_word(9,247);mtu_exchanged<=1;
                        att_mtu<=word_at(9)<23 ? 23 : word_at(9)>247 ? 247 : word_at(9);
                    end
                end
                8'h06: begin
                    if(captured_length!=17) att_error_response(6,0,8'h04);
                    else if(start_handle==0 || start_handle>end_handle)
                        att_error_response(6,start_handle,1);
                    else begin
                        // Each supported service UUID has exactly one range.
                        used=word_at(15)==16'h1800 ? 1 :
                             word_at(15)==16'h1801 ? 4 :
                             word_at(15)==16'hfff0 ? 5 : 0;
                        if(attribute_type!=16'h2800 || used==0 ||
                           used<start_handle || used>end_handle)
                            att_error_response(6,start_handle,8'h0a);
                        else begin
                            response[response_base+8]=7;
                            response_word(9,used);
                            response_word(11,used==1 ? 3 : used==4 ? 4 : 8);
                            response_begin(4,5);
                        end
                    end
                end
                8'h10: begin
                    if(captured_length!=15) att_error_response(8'h10,0,8'h04);
                    else if(start_handle==0 || start_handle>end_handle)
                        att_error_response(8'h10,start_handle,1);
                    else if(attribute_type!=16'h2800)
                        att_error_response(8'h10,start_handle,8'h10);
                    else begin
                        first_in_range=start_handle<=1 && end_handle>=1;
                        second_in_range=start_handle<=4 && end_handle>=4;
                        third_in_range=start_handle<=5 && end_handle>=5;
                        used=first_in_range+second_in_range+third_in_range;
                        response[response_base+8]=8'h11;
                        response[response_base+9]=6;
                        // Pack the ordered service ranges into fixed slots.
                        if(used!=0) begin
                            response_word(10,first_in_range ? 1 : second_in_range ? 4 : 5);
                            response_word(12,first_in_range ? 3 : second_in_range ? 4 : 8);
                            response_word(14,first_in_range ? 16'h1800 :
                                             second_in_range ? 16'h1801 : 16'hfff0);
                        end
                        if(used>=2) begin
                            response_word(16,first_in_range && second_in_range ? 4 : 5);
                            response_word(18,first_in_range && second_in_range ? 4 : 8);
                            response_word(20,first_in_range && second_in_range ? 16'h1801 : 16'hfff0);
                        end
                        if(used==3) begin
                            response_word(22,5); response_word(24,8); response_word(26,16'hfff0);
                        end
                        if(used==0) att_error_response(8'h10,start_handle,8'h0a);
                        else response_begin(4,used==1 ? 8 : used==2 ? 14 : 20);
                    end
                end
                8'h08: begin
                    if(captured_length!=15) att_error_response(8,0,8'h04);
                    else if(start_handle==0 || start_handle>end_handle)
                        att_error_response(8,start_handle,1);
                    else begin
                        response[response_base+8]=9; used=2;
                        if(attribute_type==16'h2803) begin
                            first_in_range=start_handle<=2 && end_handle>=2;
                            second_in_range=start_handle<=6 && end_handle>=6;
                            response[response_base+9]=7;
                            if(first_in_range || second_in_range) begin
                                response_word(10,first_in_range ? 2 : 6);
                                response[response_base+12]=first_in_range ? 2 : 8'h12;
                                response_word(13,first_in_range ? 3 : 7);
                                response_word(15,first_in_range ? 16'h2a00 : 16'hfff1);
                                used=9;
                            end
                            if(first_in_range && second_in_range) begin
                                response_word(17,6); response[response_base+19]=8'h12;
                                response_word(20,7); response_word(22,16'hfff1);
                                used=16;
                            end
                        end else if(attribute_type==16'h2a00 &&
                                    start_handle<=3 && end_handle>=3) begin
                            response[response_base+9]=13; response_word(10,3);
                            for(i=0;i<11;i=i+1)
                                response[response_base+12+i]=name_byte(i);
                            used=15;
                        end
                        if(used==2) att_error_response(8,start_handle,8'h0a);
                        else response_begin(4,used);
                    end
                end
                8'h04: begin
                    if(captured_length!=13) att_error_response(4,0,8'h04);
                    else if(start_handle==0 || start_handle>end_handle)
                        att_error_response(4,start_handle,1);
                    else if(start_handle>8) att_error_response(4,start_handle,8'h0a);
                    else begin
                        response[response_base+8]=5;
                        response[response_base+9]=1;
                        // Preserve the legacy five-entry cap even at MTU 247.
                        // Fixed slots avoid a dependent variable write address;
                        // gate unused slots so their previous bytes stay intact.
                        used=(end_handle<8 ? end_handle : 8)-start_handle+1;
                        if(used>5) used=5;
                        for(i=0;i<5;i=i+1) begin
                            if(i<used) begin
                                response_word(10+4*i,start_handle+i);
                                response_word(12+4*i,attribute_uuid(start_handle+i));
                            end
                        end
                        response_begin(4,2+4*used);
                    end
                end
                8'h0a: begin
                    if(captured_length!=11) att_error_response(8'h0a,0,8'h04);
                    else if(start_handle==3) begin
                        response_begin(4,12); response[response_base+8]=8'h0b;
                        for(i=0;i<11;i=i+1) response[response_base+9+i]=name_byte(i);
                    end else if(start_handle==7) begin
                        response_begin(4,21); response[response_base+8]=8'h0b;
                        value_begin(0);
                    end else if(start_handle==8) begin
                        response_begin(4,3); response[response_base+8]=8'h0b;
                        response_word(9,{15'b0,subscribed});
                    end else att_error_response(8'h0a,start_handle,
                                        start_handle==0 || start_handle>8 ? 1 : 2);
                end
                8'h12,8'h52: begin
                    if(captured_length<11) begin
                        if(packet[8]==8'h12) att_error_response(8'h12,0,8'h04);
                    end else if(start_handle==8 &&
                       captured_length==13 && word_at(11)<=1) begin
                        subscribed <= packet[11][0];
                        notify_deadline <= elapsed_ms+NOTIFY_MS;
                        if(packet[8]==8'h12) begin
                            response_begin(4,1); response[response_base+8]=8'h13;
                        end
                    end else if(packet[8]==8'h12)
                        att_error_response(8'h12,start_handle,
                                           start_handle==8 ? 8'h0d : 3);
                end
                8'h1e: begin end // Confirmation has no ATT response.
                default: att_error_response(packet[8],
                            captured_length>=11 ? start_handle : 0,6);
            endcase
        end
    endtask

    always @(posedge clk)begin
        if(resetn && enable && state==BIZ_BUILD && business_bulk && !capture_wait)
            bulk_tx[business_index[7:0]]<=business_byte(business_index);
        bulk_data<=bulk_tx[tx_payload_addr[7:0]];
    end
    always @(posedge clk) begin
        if(!resetn || !enable) begin
            state<=IDLE; captured_type<=0; captured_length<=0;
            rx_payload_addr<=0; rx_consume<=0; tx_start<=0; tx_length<=0;
            connected<=0; subscribed<=0; connection_handle<=0;
            notification_count<=0; acl_rx_count<=0; att_request_count<=0;
            completed_packets<=0; error_count<=0; elapsed_ms<=0;
            ms_divider<=0; notify_deadline<=NOTIFY_MS;
            response_subscribed<=0; status_subscribed<=0; transfer_subscribed<=0;
            fragment_start<=0; reply_consume<=0; summary_latch<=0;transfer_consume<=0;
            business_index<=0; business_length<=0; business_kind<=0;
            fragment_length<=0; business_token<=1; business_fragment<=0;
            business_offset<=0; business_data_length<=0;business_compact<=0;business_bulk<=0; summary_wait<=0;business_transfer<=0;
            capture_wait<=1; active_hci<=0;active_bulk<=0;att_mtu<=23;mtu_exchanged<=0; fast_link_pending<=0;fast_link_requested<=0;advertise_pending<=0; advertise_wait<=0; advertise_time<=0;
            completion_handle<=0;completion_count_low<=0;completion_sum<=0;
            value_notification<=0;value_index<=0;value_crc<=16'hffff;
            value_sequence<=0;value_milliseconds<=0;
            queued<=0; read_slot<=0; write_slot<=0; tx_busy<=0; tx_credits<=1;
        end else begin
            rx_consume<=0; tx_start<=0;
            fragment_start<=0; reply_consume<=0; summary_latch<=0;transfer_consume<=0;
            if(advertise_wait && elapsed_ms-advertise_time>=2000) begin
                advertise_wait<=0; error_count<=error_count+1'b1;
            end
            if(ms_divider>=MS_CYCLES-1) begin
                ms_divider<=0; elapsed_ms<=elapsed_ms+1'b1;
            end else ms_divider<=ms_divider+1'b1;
            if(tx_busy && (tx_done || tx_error)) begin
                tx_busy<=0;
                if(tx_error) error_count<=error_count+1'b1;
            end
            case(state)
                IDLE: begin
                    if(rx_valid) begin
                        if(rx_length==0 || rx_length>264) begin
                            rx_consume<=1; error_count<=error_count+1'b1;
                            state<=WAIT_DROP;
                        end else begin
                            captured_type<=rx_type; captured_length<=rx_length;
                            rx_payload_addr<=0; capture_wait<=1;completion_sum<=0;state<=CAPTURE;
                        end
                    end else if(reply_valid && transfer_direct && response_is_data) begin
                        // OPEN_DIRECT: the unchanged, CRC-protected DATA is the
                        // positive READ/ACK_READ receipt. Keep cached replies for
                        // exact retries, but omit only their successful wire copy.
                        reply_consume<=1;
                    end else if(!tx_busy && tx_ready && !connected && advertise_pending) begin
                        active_hci<=1;active_bulk<=0;
                        active_tx[0]<=8'h0a; active_tx[1]<=8'h20;
                        active_tx[2]<=1; active_tx[3]<=1;
                        tx_length<=4; tx_start<=1; tx_busy<=1;
                        advertise_pending<=0; advertise_wait<=1; advertise_time<=elapsed_ms;
                    end else if(!tx_busy && tx_ready && tx_credit && connected && fast_link_pending && queued==0) begin
                        // BLE 4.0 peripheral requests link parameters over LE
                        // signaling CID 5. HCI LE Connection Update is a central
                        // procedure on this controller. Ask for 15ms, latency0,
                        // 4s supervision; rejection keeps the current link.
                        active_hci<=0;active_bulk<=0;fast_link_pending<=0;fast_link_requested<=1;
                        active_tx[0]<=connection_handle[7:0];active_tx[1]<={4'd0,connection_handle[11:8]};
                        active_tx[2]<=16;active_tx[3]<=0;active_tx[4]<=12;active_tx[5]<=0;
                        active_tx[6]<=5;active_tx[7]<=0;active_tx[8]<=8'h12;active_tx[9]<=8'h25;
                        active_tx[10]<=8;active_tx[11]<=0;
                        active_tx[12]<=12;active_tx[13]<=0;active_tx[14]<=12;active_tx[15]<=0;
                        active_tx[16]<=0;active_tx[17]<=0;active_tx[18]<=8'h90;active_tx[19]<=1;
                        tx_length<=20;tx_start<=1;tx_busy<=1;if(!SHARED_HCI_OWNER)tx_credits<=tx_credits-1'b1;
                    end else if(!tx_busy && tx_ready && tx_credit && queued!=0) begin
                        active_hci<=0;active_bulk<=0;
                        for(i=0;i<32;i=i+1) begin
                            if(read_slot) active_tx[i]<=response[32+i];
                            else active_tx[i]<=response[i];
                        end
                        tx_length<=response_length[read_slot]; tx_start<=1;
                        read_slot<=~read_slot; queued<=queued-1'b1;
                        tx_busy<=1; if(!SHARED_HCI_OWNER)tx_credits<=tx_credits-1'b1;
                    end else if(!tx_busy && tx_ready && tx_credit && queued==0 &&
                                connected && ((response_subscribed && reply_valid) || (transfer_subscribed && transfer_valid))) begin
                        response_base=write_slot ? 32 : 0;
                        // OPEN_COMPACT explicitly opts DATA into B2: four-byte
                        // header, sixteen payload bytes, same 20-byte ATT value.
                        business_compact<=!reply_valid && transfer_compact;
                        business_bulk<=!reply_valid && transfer_bulk;
                        if(!reply_valid && transfer_bulk)begin
                            business_data_length<=next_reply_length-business_offset>bulk_capacity ? bulk_capacity : next_reply_length-business_offset;
                            business_length<=15+(next_reply_length-business_offset>bulk_capacity ? bulk_capacity : next_reply_length-business_offset);
                        end else if(!reply_valid && transfer_compact) begin
                            business_data_length<=next_reply_length-business_offset>16 ? 16 : next_reply_length-business_offset;
                            business_length<=15+(next_reply_length-business_offset>16 ? 16 : next_reply_length-business_offset);
                        end else begin
                            business_data_length<=next_reply_length-business_offset>14 ? 14 : next_reply_length-business_offset;
                            business_length<=17+(next_reply_length-business_offset>14 ? 14 : next_reply_length-business_offset);
                        end
                        business_kind<=1;business_transfer<=!reply_valid; business_index<=0; capture_wait<=1;state<=BIZ_BUILD;
                    end else if(!tx_busy && tx_ready && tx_credit && queued==0 &&
                                connected && subscribed &&
                                $signed(elapsed_ms-notify_deadline)>=0) begin
                        active_hci<=0;active_bulk<=0;
                        active_tx[0]<=connection_handle[7:0];
                        active_tx[1]<={4'b0000,connection_handle[11:8]};
                        active_tx[2]<=27; active_tx[3]<=0;
                        active_tx[4]<=23; active_tx[5]<=0;
                        active_tx[6]<=4; active_tx[7]<=0;
                        active_tx[8]<=8'h1b; active_tx[9]<=7; active_tx[10]<=0;
                        value_begin(1);
                        notify_deadline<=elapsed_ms+NOTIFY_MS;
                    end
                end
                CAPTURE: begin
                    if(capture_wait) capture_wait<=0;
                    else begin
                        capture_wait<=1;
                        if(rx_payload_addr<32)packet[rx_payload_addr]<=rx_payload_data;
                        if(captured_type==4 && packet[0]==8'h13 && rx_payload_addr>=3) begin
                            case(rx_payload_addr[1:0])
                                3:completion_handle[7:0]<=rx_payload_data;
                                0:completion_handle[11:8]<=rx_payload_data[3:0];
                                1:completion_count_low<=rx_payload_data;
                                2:if(connected && completion_handle==connection_handle)
                                    completion_sum<=completion_sum+{rx_payload_data,completion_count_low};
                            endcase
                        end
                        if(rx_payload_addr+1'b1==captured_length) begin rx_consume<=1;state<=PARSE;end
                        else rx_payload_addr<=rx_payload_addr+1'b1;
                    end
                end
                PARSE: begin
                    state<=IDLE;
                    response_base=write_slot ? 32 : 0;
                    if(captured_type==4 && captured_length>=2 &&
                       captured_length==packet[1]+2) begin
                        if(packet[0]==8'h3e && captured_length>=21 &&
                           (packet[2]==1 || packet[2]==8'h0a) && packet[3]==0) begin
                            connected<=1; subscribed<=0;att_mtu<=23;mtu_exchanged<=0;
                            response_subscribed<=0; status_subscribed<=0; transfer_subscribed<=0;
                            business_token<=1; business_fragment<=0; business_offset<=0;
                            connection_handle<=word_at(4)&16'h0fff;
                            fast_link_pending<=0;fast_link_requested<=0;
                            tx_credits<=credit_limit; queued<=0; read_slot<=0; write_slot<=0;
                            notify_deadline<=elapsed_ms+NOTIFY_MS;
                        end else if(packet[0]==5 && captured_length==6 &&
                                    packet[2]==0 &&
                                    (word_at(3)&16'h0fff)==connection_handle) begin
                            connected<=0; subscribed<=0;fast_link_pending<=0;fast_link_requested<=0;
                            response_subscribed<=0; status_subscribed<=0; transfer_subscribed<=0;
                            advertise_pending<=1;
                            queued<=0; read_slot<=0; write_slot<=0;
                        end else if(packet[0]==8'h0e && captured_length==6 &&
                                    packet[3]==8'h0a && packet[4]==8'h20 && advertise_wait) begin
                            advertise_wait<=0;
                            if(packet[5]!=0) error_count<=error_count+1'b1;
                        end else if(packet[0]==8'h13 && captured_length>=7 &&
                                    captured_length==3+packet[2]*4) begin
                            state<=COMPLETIONS;
                        end
                    end else if(captured_type==2) begin
                        // Continuations are explicitly rejected: this fixed MTU
                        // peripheral supports only complete LE L2CAP packets.
                        if(captured_length<8 || !connected ||
                           (word_at(0)&16'h0fff)!=connection_handle ||
                           (packet[1][5:4]!=0 && packet[1][5:4]!=2) ||
                           packet[1][7:6]!=0 ||
                           word_at(2)!=captured_length-4 ||
                           word_at(4)!=captured_length-8) begin
                            error_count<=error_count+1'b1;
                        end else begin
                            acl_rx_count<=acl_rx_count+1'b1;
                            if(word_at(6)==4 && captured_length>8) begin
                                att_request_count<=att_request_count+1'b1;
                                if(queued==2) error_count<=error_count+1'b1;
                                else if((packet[8]==8'h10 && word_at(9)>5) ||
                                    (packet[8]==8'h08 && word_at(9)>6) ||
                                    (packet[8]==4 && word_at(9)>8) ||
                                    (packet[8]==6 && captured_length==31) ||
                                    ((packet[8]==8'h0a || packet[8]==8'h12 || packet[8]==8'h52) && word_at(9)>=9))
                                    process_business_att();
                                else process_att();
                            end else if(word_at(6)==5 && captured_length>=12) begin
                                // Responses are terminal even when the peer
                                // rejects our request; never reject a response.
                                if(packet[8]==8'h13 || packet[8]==1) begin
                                    if((packet[8]==8'h13 && (captured_length!=14 || word_at(10)!=2 || word_at(12)>1)) ||
                                       (packet[8]==1 && captured_length<14)) error_count<=error_count+1'b1;
                                end else if(queued==2) error_count<=error_count+1'b1;
                                else begin
                                    response_begin(5,6);
                                    response[response_base+8]=1;
                                    response[response_base+9]=packet[9];
                                    response_word(10,2); response_word(12,0);
                                end
                            end
                        end
                    end
                end
                COMPLETIONS: begin
                    if(connected && completion_sum!=0) begin
                        completed_packets<=completed_packets+completion_sum;
                        if(!SHARED_HCI_OWNER && tx_credits+completion_sum>=credit_limit)tx_credits<=credit_limit;
                        else if(!SHARED_HCI_OWNER)tx_credits<=tx_credits+completion_sum;
                    end
                    state<=IDLE;
                end
                BIZ_COPY: begin
                    if(business_index+1==fragment_length) begin
                        fragment_start<=1; summary_wait<=0; state<=BIZ_WAIT;
                    end else business_index<=business_index+1'b1;
                end
                BIZ_WAIT: begin
                    if(summary_wait==1) summary_wait<=2;
                    else if(summary_wait==2) begin
                        business_att[0]=8'h0b;
                        for(i=0;i<20;i=i+1) business_att[i+1]=summary_value>>(8*i);
                        summary_wait<=0; business_begin(21);
                    end else if(fragment_done) begin
                        if(packet[8]!=8'h52) begin
                            if(fragment_error!=0) att_error_response(8'h12,13,fragment_error);
                            else begin response_begin(4,1); response[response_base+8]=8'h13; end
                        end
                        state<=IDLE;
                    end
                end
                BIZ_BUILD: if(capture_wait) capture_wait<=0;else begin
                    capture_wait<=1;
                    if(!business_bulk)response[response_base+business_index[4:0]]=business_byte(business_index);
                    if(business_index+1==business_length) begin
                        if(business_bulk)begin
                            // The block RAM is retained until the ACL bridge has
                            // copied and acknowledged every physical segment.
                            active_hci<=0;active_bulk<=1;tx_length<=business_length;
                            tx_start<=1;tx_busy<=1;if(!SHARED_HCI_OWNER)tx_credits<=tx_credits-1'b1;
                        end else begin
                            response_length[write_slot]<=business_length;
                            write_slot<=~write_slot; queued<=queued+1'b1;
                        end
                        if(business_kind==1) begin
                            if(business_offset+business_data_length==active_reply_length) begin
                                if(business_transfer) transfer_consume<=1;else reply_consume<=1; business_offset<=0; business_fragment<=0;
                                business_token<=business_token+1'b1;
                            end else begin
                                business_offset<=business_offset+business_data_length;
                                business_fragment<=business_fragment+1'b1;
                            end
                        end
                        state<=IDLE;
                    end else business_index<=business_index+1'b1;
                end
                VALUE_BUILD: begin
                    if(value_index<18) begin
                        if(value_notification)active_tx[11+value_index]<=value_byte;
                        else response[response_base+9+value_index]=value_byte;
                        value_crc<=crc_byte(value_crc,value_byte);
                    end else if(value_index==18) begin
                        if(value_notification)active_tx[29]<=value_crc[7:0];
                        else response[response_base+27]=value_crc[7:0];
                    end else begin
                        if(value_notification) begin
                            active_tx[30]<=value_crc[15:8];
                            tx_length<=31;tx_start<=1;tx_busy<=1;
                            if(!SHARED_HCI_OWNER)tx_credits<=tx_credits-1'b1;
                            notification_count<=notification_count+1'b1;
                        end else response[response_base+28]=value_crc[15:8];
                        state<=IDLE;
                    end
                    value_index<=value_index+1'b1;
                end
                WAIT_DROP: if(!rx_valid) state<=IDLE;
                default: state<=IDLE;
            endcase
        end
    end
endmodule
